package finance.bank;
public final class BankLiquidityService {private BankLiquidityService(){}public static boolean ensureReserves(java.util.UUID bankId,long minimum,long day){CommercialBank b=BankingManager.bank(bankId);if(b==null||minimum<0)return false;if(b.ledger().balance(BankLedgerAccount.ASSET_RESERVE)>=minimum)return true;InterbankMarketService.borrowFor(bankId,minimum,day);if(b.ledger().balance(BankLedgerAccount.ASSET_RESERVE)<minimum)CentralBankLiquidityService.borrow(bankId,minimum-b.ledger().balance(BankLedgerAccount.ASSET_RESERVE),day);return b.ledger().balance(BankLedgerAccount.ASSET_RESERVE)>=minimum;}}
